-- ScholarBridgeAi — Scholarship rewrite pass 37 (Belgium)
-- Verified 2026-10-25 against the providers' own pages (cited in source_url).
-- Belgium splits in two, and the split decides everything for a student from Uzbekistan.
-- Flanders has Master Mind: EUR 10,000-10,225 a year plus a full tuition waiver, open to every
-- nationality except Russian, but the student cannot apply - the institution nominates.
-- Wallonia-Brussels has the WBI Master IN scholarship: EUR 10,020 in twelve instalments, and
-- UCLouvain states in its own FAQ that it grants no scholarships of its own to international students.
-- Values are in EUR; amount_usd_value stays 0 for non-USD awards.

-- 581 Ghent University — the Master Mind scholarship, which is nominated rather than applied for
UPDATE scholarships SET
  title = 'Master Mind Scholarship at Ghent University',
  description = 'This record was called the Ghent University Top-up Grant, and the honest correction is that Ghent''s current Global South funding page no longer lists a Top-up Grant at all: what it lists now is ICP Connect under VLIR-UOS, research backpacks and the Master Mind scholarship. Master Mind is the real Flemish instrument and it is worth the whole record. It pays a maximum of EUR 10,000 per academic year at Ghent - EUR 10,225 under the Flemish Government call - for one academic year on a 60-ECTS master and two years on a 120-ECTS master, and it comes with a full tuition waiver: the holder pays only the lowest Flemish study-grant rate, which was EUR 136.5 for 2025-26, instead of the international fee of several thousand euros. The competition is tiny and it is not an open competition: roughly thirty students are funded across all Flemish institutions and Ghent expects about six of them, so the practical odds are set by whether your programme coordinator puts your name forward. A student cannot apply directly. The coordinator proposes at most two applicants per programme, the International Relations Office screens every file and forwards a shortlist of at most twenty to the Flemish Government by the end of April, and shortlisted candidates are contacted in mid-April to complete the Mobility Online application. The academic bar is a GPA of 3.5 out of 4.0 and good English. Admission must be applied for before 1 April, and all nationalities are eligible except Russian citizens.',
  requirements = 'Apply for academic admission to a Ghent University master programme, including advanced masters, before 1 April, because only academically admitted students are considered and the scholarship is built into the normal admission scheme. Hold a GPA of 3.5 out of 4.0 in the last obtained bachelor or master degree and demonstrate good command of English. Your previous degree must not have been obtained at a Flemish institution, and you must not already be enrolled at one, with the single exception of students in a spring preparatory programme that leads into a September master. Be proposed by your master programme coordinator, who may put forward at most two applicants per programme; a student cannot apply directly. If shortlisted by the International Relations Office, complete the Mobility Online application in mid-April. Keep at least half of the study credits at the Flemish host institution, and note that preparatory, bridging and distance-learning programmes are not eligible.',
  coverage_type = 'Full Funding', award_basis = 'fixed', award_amount = 10000, award_currency = 'EUR', award_period = 'year',
  degree_levels = '["Master''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Government scholarship with tuition waiver',
  tuition_coverage = 'EUR 10,000 per academic year at Ghent, or EUR 10,225 under the Flemish Government call, for one year on a 60-ECTS master and two years on a 120-ECTS master, plus a full tuition waiver under which the holder pays only the Flemish study-grant rate of about EUR 136.5 a year. The grant is paid in instalments and covers accommodation, insurance and a large part of living costs.',
  english_requirements = 'Applicants must demonstrate good knowledge and command of English regardless of the programme minimum, which in practice means evidence around IELTS 7.0 or TOEFL 94.',
  required_documents = '["Ghent University admission application submitted before 1 April","Academic transcripts showing the GPA","English proficiency evidence","Motivation letter and ranking support from the programme coordinator","Mobility Online application if shortlisted","Passport copy"]',
  deadline = '1 April for academic admission at Ghent; shortlisted candidates complete Mobility Online in mid-April and the institution submits to the Flemish Government by the end of April',
  deadline_date = '2027-04-01', deadline_type = 'annual', application_status = 'upcoming',
  website_url = 'https://www.ugent.be/en/research/funding/globalsouth/master-mind',
  source_url = 'https://www.ugent.be/en/research/funding/globalsouth/master-mind',
  application_url = 'https://www.ugent.be/prospective-students/en/administration/application/application-degree',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from two Ghent University own pages fetched 2026-10-25: the Master Mind page at ugent.be/en/research/funding/globalsouth/master-mind states that around thirty international students are funded across the Flemish institutions with roughly six at Ghent, that the duration is one academic year for a 60-ECTS master and two for a 120-ECTS master, that the incoming student receives a maximum of EUR 10,000 per academic year, that Ghent charges the lowest Flemish study-grant tuition rate which was EUR 136.5 for 2025-26, that all new international students admitted to any master programme including advanced masters are eligible, that the applicant needs a GPA of 3.5 out of 4.0 and good English, that the application for academic admission must be submitted before 1 April, that a student cannot apply before being preselected by the master programme coordinator who proposes at most two applicants per programme, and that the International Relations Office screens the files and submits a shortlist of at most twenty to the Flemish Government by the end of April with shortlisted candidates completing Mobility Online in mid-April; the Global South grants page fetched the same day lists ICP Connect under VLIR-UOS, the IFS research backpacks and the master and doctoral schemes, and no longer lists a Top-up Grant. CORRECTIONS: the row was titled Ghent University Top-up Grant, carried an invented USD 2,438, claimed all three degree levels and gave a 1 March deadline for September entry. The Top-up Grant no longer appears on Ghent''s current Global South funding page, so the record was re-pointed at Master Mind, which is the instrument Ghent actually promotes, and the description explains the inversion that matters: a student cannot apply for it, a programme coordinator must nominate. award_amount carries Ghent''s own published figure of EUR 10,000, with the Flemish Government''s EUR 10,225 noted.'
WHERE id = 581;

-- 700 UCLouvain — UCLouvain grants no scholarships of its own; the route is WBI Master IN
UPDATE scholarships SET
  title = 'WBI Master IN Scholarship (UCLouvain and Wallonia-Brussels institutions)',
  description = 'UCLouvain answers this question itself, and the answer is the most useful sentence in the whole record: on its own FAQ the university states that UCLouvain does not grant scholarships to international bachelor''s or master''s students, and points instead at ARES-CCD, the Belgian development cooperation, the Agence Universitaire de la Francophonie and Erasmus Mundus. What does exist is the Wallonia-Brussels International Master IN scholarship, which is a regional award usable at UCLouvain and at every other French-speaking institution in Belgium. It pays EUR 10,020 split into twelve monthly instalments, and the official page is unusually candid about what that means: it does not cover the total cost of a study year, so the winner has to add their own funds. It is incompatible with any other WBI or ARES support. On the plus side the amount satisfies the financial-means requirement for a long-stay D study visa, the winner is exempt from the Aliens Office administrative fee, and WBI covers health insurance, repatriation and civil liability; visa fees are paid up front by the candidate and only recovered through the monthly instalments, and travel insurance is not covered. The eligibility rules are strict in ways that catch people out: the last bachelor or master must have been awarded no more than five years before the programme starts, the scholarship cannot fund a full 60-ECTS bridging year, applicants already studying in Belgium are excluded, and the file must be sent to the institution by 31 March at midnight. Brazil, Canada, Chile, Colombia, South Korea, Japan, Lebanon, Morocco, Mexico, the United Kingdom, Switzerland, Taiwan, Tunisia and the United States are treated as priority countries, but they are a preference rather than a restriction, so an applicant from Uzbekistan can still compete. At faculty level there is one further exception worth knowing: the EPL Excellence Scholarships cover the full UCLouvain tuition fee for the two-year engineering master''s.',
  requirements = 'Hold a bachelor''s or master''s degree awarded by an institution recognised by the higher education authorities of your own country, and have obtained that last degree no more than five years before the start of the programme applied for. First submit an admission application to the UCLouvain master programme, since a candidate must be admitted to apply and enrolled to benefit, and quote the admission file reference in the scholarship form. Send the scholarship form and all supporting documents to the institution by 31 March at midnight Brussels time. Not be already engaged in a course of higher education in Belgium, and not be extending an Erasmus+ stay or a previous free-mover enrolment. Accept that the award cannot fund a full 60-ECTS bridging year and cannot be combined with another WBI or ARES grant. Note that UCLouvain''s own FAQ states that the university does not grant scholarships to international bachelor''s or master''s students, so this regional scheme is the route rather than an UCLouvain award.',
  coverage_type = 'Partial Funding', award_basis = 'fixed', award_amount = 10020, award_currency = 'EUR', award_period = 'total',
  degree_levels = '["Master''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Regional government scholarship',
  tuition_coverage = 'EUR 10,020 paid in twelve monthly instalments, explicitly not enough to cover the whole cost of a study year, so the winner must add own funds. It counts towards the D-visa financial requirement, exempts the holder from the Aliens Office fee, and includes health, repatriation and civil liability insurance. Tuition itself is not separately waived.',
  english_requirements = 'The scholarship sets no separate English score, but most UCLouvain master programmes are taught in French and require proof of French, while the English-taught programmes set their own English requirement.',
  required_documents = '["UCLouvain admission application and its file reference","WBI scholarship application form","Bachelor or master diploma showing the award date","Academic transcripts","Passport copy","Language proficiency evidence for the programme","Proof of admission eligibility"]',
  deadline = '31 March, midnight Brussels time, for the following academic year',
  deadline_date = '2027-03-31', deadline_type = 'annual', application_status = 'upcoming',
  website_url = 'https://www.studyinbelgium.be/fr/bourse-master-wbi',
  source_url = 'https://www.studyinbelgium.be/fr/aide-financiere-bourses-master-wbi',
  application_url = 'https://www.studyinbelgium.be/fr/comment-postuler-la-bourse-master-wbi',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from three sources read on 2026-10-25: the UCLouvain FAQ on international bachelor and master applications states that UCLouvain does not grant scholarships to international bachelor or master students and points to ARES-CCD, the DGD, the AUF and Erasmus Mundus; the official studyinbelgium.be WBI Master IN page lists the eligibility conditions - a first-cycle or master diploma recognised in the candidate''s country, the last degree awarded no more than five years before the programme start, no funding for a full 60-ECTS bridging year, admission required before applying and enrolment required to benefit, exclusion of candidates already engaged in higher education in Belgium, the admission file reference to be quoted, the priority list of Brazil, Canada, Chile, Colombia, South Korea, Japan, Lebanon, Morocco, Mexico, the United Kingdom, Switzerland, Taiwan, Tunisia and the United States, the exclusion of candidates who already received an ARES development cooperation scholarship, and the 31 March midnight deadline with incomplete files not submitted to the jury; the WBI financial aid page states that the scholarship is EUR 10,020 divided into twelve monthly instalments, that it does not cover the total cost of a study year so the winner must complete it with own funds, that it is incompatible with other WBI or ARES support, that the amount meets the long-stay D visa financial requirement, that the winner is exempt from the Aliens Office administrative fee, that visa costs are advanced by the candidate and only indirectly reimbursed, and that WBI covers health, repatriation and civil liability insurance while travel insurance remains the candidate''s. CORRECTIONS: the row was titled UCLouvain Scholarships, carried an invented USD 1,125, claimed all three degree levels and gave a 30 April and 30 November deadline. UCLouvain states it grants no such scholarships, so the record was re-pointed at the regional WBI Master IN award that is actually available at UCLouvain, with the amount, the shortfall warning and the five-year rule now stated. award_amount carries the published EUR 10,020.'
WHERE id = 700;

-- 785 Vrije Universiteit Brussel — Master Mind under the Flemish Government call
UPDATE scholarships SET
  title = 'Master Mind Scholarship at Vrije Universiteit Brussel',
  description = 'Brussels has two scholarship systems and they are not interchangeable: the Vrije Universiteit Brussel sits in Flanders, so the Flemish Master Mind scholarship applies to it, while the French-speaking institutions across the city use the Wallonia-Brussels WBI scheme. Master Mind is the larger of the two. It pays EUR 10,225 per academic year, for one year on a 60-ECTS master and two years on a 120-ECTS master, which means up to EUR 20,450 across a two-year degree, and it adds a full tuition fee waiver so the holder pays only an administrative fee of around EUR 136.50 to 140 instead of the international rate. The Flemish Government funds about thirty students a year across all Flemish institutions from a budget of EUR 480,000, and thirteen of those places are carved out in advance for Japan, Mexico, Palestine and the United States, leaving roughly seventeen contested by every other nationality. The rules that decide eligibility are simple but hard: a GPA of 3.5 out of 4.0 is a floor rather than a preference, the previous degree must not come from a Flemish institution, students already enrolled in Flanders are excluded except those in a spring preparatory programme, and preparatory, bridging and distance-learning programmes do not qualify. A student cannot apply directly: the host institution nominates, each institution may submit at most twenty applications, and the 2026-27 cycle closed with institutions submitting to the Flemish government by 27 April 2026. The grant cannot be combined with another Flemish government scholarship, an Erasmus Mundus award, a BAEF or a Fulbright. The scheme is explicitly under review, so the amount and modalities may change for 2027-28.',
  requirements = 'Be admitted to a master programme at the Vrije Universiteit Brussel of at least 60 ECTS per academic year, in a programme that is not preparatory, bridging or distance learning. Hold a GPA of 3.5 out of 4.0 calculated on the last bachelor or master degree obtained, and demonstrate good command of English beyond the programme minimum. Your previous degree must not have been obtained at a Flemish higher education institution, and you must not already be enrolled at one, except as a student in a spring preparatory programme that leads directly into a September master. Keep at least half of the programme credits at the Flemish host institution. Obtain the institution nomination, since a student cannot apply directly and each institution may submit at most twenty applications to the Flemish Government. Complete the Mobility Online application if nominated, and hold no other Flemish government, Erasmus Mundus, BAEF or Fulbright scholarship.',
  coverage_type = 'Full Funding', award_basis = 'fixed', award_amount = 10225, award_currency = 'EUR', award_period = 'year',
  degree_levels = '["Master''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Government scholarship with tuition waiver',
  tuition_coverage = 'EUR 10,225 per academic year for one year on a 60-ECTS master and two years on a 120-ECTS master, so up to EUR 20,450, plus a full tuition fee waiver leaving only an administrative fee of about EUR 136.50 to 140 a year. The grant is paid in instalments and covers accommodation, insurance and much of the living cost.',
  english_requirements = 'Applicants whose first language is not English must demonstrate good knowledge and command of English beyond the programme minimum, in practice around IELTS 7.0 or TOEFL 94.',
  required_documents = '["Admission application to a VUB master programme","Academic transcripts showing the GPA on the last degree","English proficiency evidence","Motivation letter and references","Institutional nomination","Mobility Online application if nominated","Passport copy"]',
  deadline = 'The 2026-27 cycle closed with institutions submitting nominations to the Flemish Government by 27 April 2026; VUB sets an earlier internal deadline that must be checked with the university',
  deadline_date = NULL, deadline_type = 'annual', application_status = 'upcoming',
  expected_deadline_period = 'The call opens in January and the Flemish deadline is in late April; each Flemish institution sets and publishes its own earlier internal deadline, and the scheme is under review for 2027-28.',
  website_url = 'https://www.studyinflanders.be/scholarships/master-mind-scholarships',
  source_url = 'https://www.international.vluhr.be/scholarships/master-mind-scholarships',
  application_url = 'https://www.studyinflanders.be/scholarships/master-mind-scholarships/eligibility-criteria',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from the official Flemish Master Mind pages read on 2026-10-25: studyinflanders.be/scholarships/master-mind-scholarships states that the Flemish Ministry of Education and Training awards the scholarships, that a Master Mind Scholarship includes a grant of EUR 10,225 plus a tuition fee waiver per academic year, that the scholarship is currently under review and the grant, selection process and modalities may change for 2027-28, and that the 2026-27 call is closed; international.vluhr.be/scholarships/master-mind-scholarships states that the total 2026-27 budget is EUR 480,000 with an estimated thirty international students benefiting, gives the GPA floor of 3.5 out of 4.0 calculated on the last obtained bachelor or master, restricts eligibility to all nationalities except Russian, excludes preparatory, bridging and distance-learning programmes and students already enrolled in Flanders with the spring preparatory exception, sets the duration at one academic year for 60 ECTS and two for 120 ECTS with a maximum of EUR 10,225 per year and a EUR 1,525 final instalment withheld if a one-year master is not completed, and gives the timeline of a January launch, Mobility Online from 16 February 2026, the institutional deadline of 27 April 2026 at 23:59 GMT+1, selection in May and results at the end of May; studyinflanders.be adds that the grant cannot be combined with another Flemish Government scholarship, an Erasmus Mundus, BAEF or Fulbright award, and that each institution may submit a maximum of twenty applications; kuleuven.be confirms the tuition waiver with an administration fee of EUR 140 and the reserved allocations, and the published institution list gives VUB an internal deadline of 1 April 2026. CORRECTIONS: the row was titled Vrije Universiteit Brussel Scholarships, carried an invented USD 1,375, claimed all three degree levels and gave a 1 April and 1 October deadline as if it were a university award with two intakes. The real instrument is the Flemish Master Mind scholarship, it is a government award routed through the institution, it has a single annual cycle, and the student cannot apply for it directly. award_amount carries the published EUR 10,225.'
WHERE id = 785;

-- university_scholarships cards
UPDATE university_scholarships u SET scholarship_name = v.name, availability_status = 'Yes', funding_type = v.ftype, max_scholarship = v.mx, covers_tuition = true, covers_living_expenses = true, eligibility_notes = v.elig, official_url = v.url, source_url = v.url, verification_status = 'verified', last_verified_at = now()
FROM (VALUES
  (136, 'Master Mind Scholarship at Ghent University', 'Government scholarship with tuition waiver', 'EUR 10,000 a year plus a full tuition waiver, for one or two years', 'About six of the thirty Flemish Master Mind awards go to Ghent. GPA 3.5 out of 4.0, admission applied for before 1 April, and the student cannot apply directly: the programme coordinator proposes at most two applicants and the International Relations Office shortlists twenty. All nationalities except Russian.', 'https://www.ugent.be/en/research/funding/globalsouth/master-mind'),
  (109, 'WBI Master IN Scholarship (UCLouvain and Wallonia-Brussels institutions)', 'Regional government scholarship', 'EUR 10,020 paid in twelve monthly instalments', 'UCLouvain states that it grants no scholarships of its own to international bachelor or master students, so this regional award is the route. The last degree must be no more than five years old, applicants already studying in Belgium are excluded, and the amount does not cover the whole study year. Deadline 31 March at midnight.', 'https://www.studyinbelgium.be/fr/bourse-master-wbi'),
  (271, 'Master Mind Scholarship at Vrije Universiteit Brussel', 'Government scholarship with tuition waiver', 'EUR 10,225 a year plus tuition waiver, up to EUR 20,450', 'The Flemish Master Mind scheme at VUB: about thirty awards across Flanders, thirteen reserved for Japan, Mexico, Palestine and the United States. GPA 3.5 out of 4.0, no prior Flemish degree, institutional nomination required with a maximum of twenty applications per institution. The scheme is under review for 2027-28.', 'https://www.studyinflanders.be/scholarships/master-mind-scholarships')
) AS v(id, name, ftype, mx, elig, url)
WHERE u.id = v.id;
